public class MarketProduct {
    private String name;
    private double price;
    private boolean organic;
    private String season;

    public MarketProduct(String name, double price, boolean organic, String season) {
        this.name = name;
        this.price = price;
        this.organic = organic;
        this.season = season;
    }

    public String getName() {
        return name;
    }

    public double getPrice() {
        return price;
    }

    public boolean isOrganic() {
        return organic;
    }

    public String getSeason() {
        return season;
    }

    @Override
    public String toString() {
        return name + " ($" + price + ", organic=" + organic + ", season=" + season + ")";
    }
}
